    "title": "Rhythmone Adapter Params",
    "description": "A schema which validates params accepted by the Rhythmone adapter",
    "type": "object",
    "properties": {
        "placementId": {
            "type": "string",
            "description": "An ID which is used to frame Rhythmone ad tag",
            "minLength": 1
        },
        "path": {
            "type": "string",
            "description": "An ID which is used to frame Rhythmone ad tag",
            "minLength": 1
        },
        "zone": {
            "type": "string",
            "description": "An ID which is used to frame Rhythmone ad tag",
            "minLength": 1
        }
    },
    "required": [
        "placementId",
        "path",
        "zone"
    ]
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "Sharethrough Adapter Params",
    "description": "A schema which validates params accepted by the Sharethrough adapter",
    "type": "object",
    "properties": {
        "pkey": {
            "type": "string",
            "description": "placement key to use."
        },
        "iframe": {
            "type": "boolean",
            "description": "whether or not to stay in iframe",
            "default": false
        },
        "iframeSize": {
            "type": "array",
            "minItems": 2,
            "maxItems": 2,
            "items": {
                "type": "integer"
            },
            "description": "iframe dimensions",
            "default": [
                0,
                0
            ]
        },
        "bidfloor": {
            "type": "number",
            "description": "The floor price, or minimum amount, a publisher will accept for an impression, given in CPM in USD"
        }
    },
    "required": [
        "pkey"
    ]
}

